   height = png_get_uint_31(png_ptr, data + 4);
   x_offset = png_get_uint_31(png_ptr, data + 8);
   y_offset = png_get_uint_31(png_ptr, data + 12);
   delay_num = png_get_uint_16(data + 16);
   delay_den = png_get_uint_16(data + 18);
