void /* PRIVATE */
png_read_reset(png_struct *png_ptr)
{
   png_ptr->mode &= ~PNG_HAVE_IDAT;
   png_ptr->mode &= ~PNG_AFTER_IDAT;
   png_ptr->row_number = 0;
   png_ptr->pass = 0;
